eline.filter(isLikely);  var h = '<h2 style="margin-bottom:16px">≡ƒôè Data Quality Agent ΓÇö Digitization Health Check</h2>';  h += '<div style="background:linear-gradient(135deg,rgba(34,197,94,.08),rgba(20,184,166,.08));border:1px solid rgba(34,197,94,.2);border-radius:12px;padding:16px;margin-bottom:20px;font-size:.82rem">';  h += '<strong>≡ƒÄ» Purpose:</strong> Proactively identify missing, incomplete, or incorrect data across the pipeline. ';  h += 'Every member interaction is an opportunity to collect and fix data for BANF\'s digitization initiative. ';  h += 'The Communication Details Drive is <strong style="color:var(--success)">currently active</strong> ΓÇö collect phone, address, and family data at every touchpoint.';  h += '</div>';  // Compute quality metrics  var noPhone = pipeline.filter(function(r) { return !r.phone; });  var noAddress = pipeline.filter(function(r) { return !r.address && !r.city; });  var noEmail = pipeline.filter(function(r) { return !r.email || r.email.indexOf('@') < 0; });  var unknownDiet = pipeline.filter(function(r) { return r.dietary === 'unknown'; });  var noFamily = likely.filter(function(r) { return r.householdType === 'family' && (!r.householdMembers || r.householdMembers.length === 0); });  var noMemberSince = pipeline.filter(function(r) { return !r.memberSince; });  var unverified = likely.filter(function(r) { return !r.commVerified; });  var totalIssues = noPhone.length + noAddress.length + noEmail.length + unknownDiet.length + noFamily.length;  // Completeness score  var fields = ['phone', 'address', 'email', 'dietary', 'householdMembers'];  var totalPoints = pipeline.length * fields.length;  var filledPoints = 0;  pipeline.forEach(function(r) {    if (r.phone) filledPoints++;    if (r.address || r.city) filledPoints++;    if (r.email && r.email.indexOf('@') >= 0) filledPoints++;    if (r.dietary && r.dietary !== 'unknown') filledPoints++;    if (r.householdMembers && r.householdMembers.length > 0) filledPoints++;  });  var completeness = totalPoints > 0 ? Math.round(filledPoints / totalPoints * 100) : 0;  h += '<div class="stat-grid" style="margin-bottom:20px">';  h += statCard('≡ƒôè', 'Data Completeness', completeness + '%', filledPoints + '/' + totalPoints + ' fields', completeness >= 80 ? 'var(--success)' : completeness >= 50 ? 'var(--warn)' : 'var(--danger)', completeness);  h += statCard('ΓÜá∩╕Å', 'Total Issues', totalIssues, 'Across all records', totalIssues === 0 ? 'var(--success)' : 'var(--danger)', Math.min(100, totalIssues * 2));  h += statCard('≡ƒô₧', 'Missing Phone', noPhone.length, '', noPhone.length === 0 ? 'var(--success)' : 'var(--danger)', noPhone.length / Math.max(pipeline.length, 1) * 100);  h += statCard('≡ƒôì', 'Missing Address', noAddress.length, '', noAddress.length === 0 ? 'var(--success)' : 'var(--warn)', noAddress.length / Math.max(pipeline.length, 1) * 100);  h += statCard('≡ƒì╜∩╕Å', 'Unknown Diet', unknownDiet.length, 'Need to collect', unknownDiet.length === 0 ? 'var(--success)' : 'var(--warn)', unknownDiet.length / Math.max(pipeline.length, 1) * 100);  h += statCard('≡ƒæ¿ΓÇì≡ƒæ⌐ΓÇì≡ƒæºΓÇì≡ƒæª', 'No Family Data', noFamily.length, 'Family accounts w/o members', noFamily.length === 0 ? 'var(--success)' : 'var(--warn)', noFamily.length / Math.max(likely.length, 1) * 100);  h += statCard('Γ£à', 'Unverified', unverified.length, 'Comm Drive pending', unverified.length === 0 ? 'var(--success)' : 'var(--info)', unverified.length / Math.max(likely.length, 1) * 100);  h += statCard('≡ƒôà', 'No Join Date', noMemberSince.length, '', noMemberSince.length === 0 ? 'var(--success)' : 'var(--muted)', noMemberSince.length / Math.max(pipeline.length, 1) * 100);  h += '</div>';  // Agent recommendations  h += '<h3 style="margin-bottom:12px">≡ƒñû Agent Data Collection Opportunities</h3>';  h += '<div style="background:var(--card);border:1px solid var(--border);border-radius:12px;padding:16px;margin-bottom:20px">';  var opps = [];  if (noPhone.length) opps.push({icon:'≡ƒô₧', text: noPhone.length + ' members missing phone ΓÇö Comm Verify Agent will request at next interaction', priority: 'high'});  if (noAddress.length) opps.push({icon:'≡ƒôì', text: noAddress.length + ' members missing address ΓÇö Comm Verify Agent will request at next interaction', priority: 'high'});  if (unknownDiet.length) opps.push({icon:'≡ƒì╜∩╕Å', text: unknownDiet.length + ' members with unknown dietary ΓÇö Email Agent will ask in next communication', priority: 'medium'});  if (noFamily.length) opps.push({icon:'≡ƒæ¿ΓÇì≡ƒæ⌐ΓÇì≡ƒæºΓÇì≡ƒæª', text: noFamily.length + ' family accounts with no family members listed ΓÇö Comm Verify will collect', priority: 'medium'});  if (unverified.length) opps.push({icon:'Γ£à', text: unverified.length + ' members unverified ΓÇö Communication Details Drive is active', priority: 'low'});  if (noMemberSince.length) opps.push({icon:'≡ƒôà', text: noMemberSince.length + ' without join date ΓÇö CRM enrichment agent will backfill', priority: 'low'});  if (opps.length === 0) {    h += '<div style="text-align:center;padding:20px;color:var(--success);font-weight:600">≡ƒÄë All data quality checks passed!</div>';  } else {    opps.forEach(function(o) {      var prColor = o.priority === 'high' ? 'var(--danger)' : o.priority === 'medium' ? 'var(--warn)' : 'var(--muted)';      h += '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)">';      h += '<span style="font-size:1.1rem">' + o.icon + '</span>';      h += '<div style="flex:1;font-size:.82rem">' + esc(o.text) + '</div>';      h += '<span class="tag" style="background:' + prColor + ';color:#fff;font-size:.58rem">' + o.priority.toUpperCase() + '</span>';      h += '</div>';    });  }  h += '</div>';  // Detailed issues table  var allIssues = [];  pipeline.forEach(function(r) {    if (!r.phone) allIssues.push({member: r.displayName, email: r.email, field: 'Phone', issue: 'Missing', fix: 'Request via Comm Verify'});    if (!r.address && !r.city) allIssues.push({member: r.displayName, email: r.email, field: 'Address', issue: 'Missing', fix: 'Request via Comm Verify'});    if (r.dietary === 'unknown') allIssues.push({member: r.displayName, email: r.email, field: 'Dietary', issue: 'Unknown', fix: 'Ask in RSVP follow-up'});    if (r.householdType === 'family' && (!r.householdMembers || r.householdMembers.length === 0) && isLikely(r)) allIssues.push({member: r.displayName, email: r.email, field: 'Family Members', issue: 'Empty', fix: 'Collect during Comm Verify'});  });  if (allIssues.length > 0) {    h += '<h3 style="margin-bottom:12px">≡ƒôï Detailed Issues (' + allIssues.length + ')</h3>';    h += '<div class="table-wrap"><table><thead><tr>';    h += '<th>Member</th><th>Field</th><th>Issue</th><th>Suggested Fix</th><th>Action</th>';    h += '</tr></thead><tbody>';    allIssues.slice(0, 50).forEach(function(iss) {      h += '<tr>';      h += '<td><strong>' + esc(iss.member) + '</strong><br><span style="font-size:.68rem;color:var(--muted)">' + esc(iss.email) + '</span></td>';      h += '<td style="font-weight:600">' + esc(iss.field) + '</td>';      h += '<td><span class="tag" style="background:rgba(239,68,68,.15);color:var(--danger)">' + esc(iss.issue) + '</span></td>';      h += '<td style="font-size:.78rem;color:var(--muted)">' + esc(iss.fix) + '</td>';      h += '<td><button class="btn sm dq-fix-btn" data-email="' + iss.email + '">≡ƒöº Fix</button></td>';      h += '</tr>';    });    h += '</tbody></table></div>';    if (allIssues.length > 50) h += '<div style="font-size:.72rem;color:var(--muted);text-align:center;margin-top:8px">Showing first 50 of ' + allIssues.length + ' issues</div>';  }  return h;}function bindDataQualityEvents() {  document.querySelectorAll('.dq-fix-btn').forEach(function(btn) {    btn.addEventListener('click', function() {      openCommVerifyModal(btn.dataset.email);    });  });}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// TEST HARNESS VIEW ΓÇö Run test personas through workflow scenarios// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction renderTestHarness() {  var scenarios = STATE.testScenarios || [];  var testRecs = STATE.pipeline.filter(function(r) { return r.isTestPersona; });  var h = '<h2 style="margin-bottom:16px">≡ƒº¬ Test Harness ΓÇö Workflow Scenario Testing</h2>';  h += '<div style="background:linear-gradient(135deg,rgba(236,72,153,.08),rgba(167,139,250,.08));border:1px solid rgba(236,72,153,.2);border-radius:12px;padding:16px;margin-bottom:20px;font-size:.82rem">';  h += '<strong>≡ƒÄ» Purpose:</strong> Before going live, test every workflow path with synthetic test personas. ';  h += 'Each persona represents a different member type (new family, returning couple, EC member, student, edge cases). ';  h += 'Run each scenario through the full 9-stage pipeline to verify the system handles all cases correctly.';  h += '<br><br><strong>ΓÜá∩╕Å Test personas</strong> are marked with ≡ƒº¬ and use @banf-test.org emails. They will not send real emails.';  h += '</div>';  // Summary stats  h += '<div class="stat-grid" style="margin-bottom:20px">';  h += statCard('≡ƒº¬', 'Test Personas', testRecs.length, '', 'var(--pink)', 100);  h += statCard('≡ƒôï', 'Test Scenarios', scenarios.length, '', 'var(--accent)', 100);  var completed = testRecs.filter(function(r) { return r.resumePoint === null; });  h += statCard('Γ£à', 'Scenarios Complete', completed.length + '/' + testRecs.length, '', 'var(--success)', completed.length / Math.max(testRecs.length, 1) * 100);  var inProgress = testRecs.filter(function(r) { return r.resumePoint && r.resumePoint !== 'membership'; });  h += statCard('≡ƒöä', 'In Progress', inProgress.length, '', 'var(--warn)', inProgress.length / Math.max(testRecs.length, 1) * 100);  h += '</div>';  // Per-scenario cards  h += '<h3 style="margin-bottom:12px">≡ƒôï Test Scenarios</h3>';  scenarios.forEach(function(sc) {    var persona = testRecs.find(function(r) { return r.id === sc.persona; });    if (!persona) return;    // Calculate completion    var stagesComplete = 0;    var stagesTotal = sc.steps.length;    sc.steps.forEach(function(step) {      var st = persona.stages[step.stage];      if (st && (st.status === 'completed' || st.status === 'skipped')) stagesComplete++;    });    var pct = Math.round(stagesComplete / stagesTotal * 100);    var isDone = pct === 100;    h += '<div style="background:var(--card);border:1px solid ' + (isDone ? 'var(--success)' : 'var(--border)') + ';border-radius:12px;padding:16px;margin-bottom:12px;position:relative">';    if (isDone) h += '<div style="position:absolute;top:12px;right:12px;font-size:1.2rem">Γ£à</div>';    // Header    h += '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">';    h += '<span class="tag" style="background:var(--pink);color:#fff">' + esc(sc.id) + '</span>';    h += '<div style="font-weight:700;font-size:.88rem">' + esc(sc.name) + '</div>';    h += '</div>';    // Persona info    h += '<div style="font-size:.78rem;color:var(--muted);margin-bottom:8px">' + esc(persona.testDescription || '') + '</div>';    h += '<div style="font-size:.72rem;color:var(--accent2);margin-bottom:10px">Persona: <strong>' + esc(persona.displayName) + '</strong> ┬╖ ' + esc(persona.email) + '</div>';    // Progress bar    h += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">';    h += '<div style="flex:1;height:6px;background:var(--border);border-radius:3px;overflow:hidden"><div style="height:100%;width:' + pct + '%;background:' + (isDone ? 'var(--success)' : 'var(--accent)') + ';border-radius:3px;transition:width .3s"></div></div>';    h += '<span style="font-size:.72rem;font-weight:700;color:' + (isDone ? 'var(--success)' : 'var(--muted)') + '">' + pct + '%</span>';    h += '</div>';    // Step breakdown    h += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:6px;font-size:.72rem">';    sc.steps.forEach(function(step, idx) {      var st = persona.stages[step.stage];      var status = st ? st.status : 'not_started';      var stepDone = (status === 'completed' || status === 'skipped');      var stepActive = (status === 'pending' || status === 'in_progress');      var stepColor = stepDone ? 'var(--success)' : stepActive ? 'var(--accent)' : 'var(--muted)';      h += '<div style="display:flex;align-items:flex-start;gap:6px;padding:4px 6px;background:' + (stepDone ? 'rgba(34,197,94,.05)' : stepActive ? 'rgba(99,102,241,.05)' : 'transparent') + ';border-radius:6px">';      h += '<span style="color:' + stepColor + ';font-weight:700;min-width:16px">' + (stepDone ? 'Γ£ô' : stepActive ? 'ΓùÅ' : 'Γùï') + '</span>';      h += '<div><div style="font-weight:600;color:' + stepColor + '">' + (idx+1) + '. ' + esc(step.stage.replace(/_/g,' ')) + '</div>';      h += '<div style="color:var(--muted)">' + esc(step.action) + '</div></div>';      h += '</div>';    });    h += '</div>';    // Expected communications    h += '<div style="margin-top:10px;font-size:.68rem;color:var(--muted)">≡ƒôº Expected comms: ' + (sc.expectedComms || []).map(function(c) { return '<span class="tag" style="font-size:.56rem">' + esc(c) + '</span>'; }).join(' ') + '</div>';    // Action buttons    h += '<div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap">';    if (!isDone) {      if (!persona.selectedCategory) {        h += '<button class="btn sm primary th-action" data-email="' + persona.email + '" data-action="membership">≡ƒÄ» Start: Select Membership</button>';      } else if (persona.paymentStatus !== 'paid' && !persona.selectedPaymentMethod){        h += '<button class="btn sm primary th-action" data-email="' + persona.email + '" data-action="payment">≡ƒÆ│ Next: Payment</button>';      } else if (!persona.commVerified) {        h += '<button class="btn sm primary th-action" data-email="' + persona.email + '" data-action="verify">Γ£à Next: Verify</button>';      } else if (!persona.driveSignupComplete) {        h += '<button class="btn sm success th-action" data-email="' + persona.email + '" data-action="drive">≡ƒô¥ Next: Drive Signup</button>';      }    }    h += '<button class="btn sm th-reset" data-email="' + persona.email + '">≡ƒöä Reset</button>';    h += '<button class="btn sm th-view" data-email="' + persona.email + '">≡ƒæü∩╕Å View Details</button>';    h += '</div></div>';  });  // Quick actions  h += '<div style="margin-top:20px;display:flex;gap:10px;flex-wrap:wrap">';  h += '<button class="btn primary" id="thResetAll">≡ƒöä Reset All Test Personas</button>';  h += '<button class="btn" id="thRunRanadhir" onclick="render(\'test_member\')">≡ƒæñ Test: Ranadhir Ghosh (Real User)</button>';  h += '</div>';  return h;}function bindTestHarnessEvents() {  document.querySelectorAll('.th-action').forEach(function(btn) {    btn.addEventListener('click', function() {      var email = btn.dataset.email;      var action = btn.dataset.action;      if (action === 'membership') openMembershipModal(email);      else if (action === 'payment') openPaymentModal(email);      else if (action === 'verify') openCommVerifyModal(email);      else if (action === 'drive') {        var rec = findRecord(email);        if (!rec) return;        var code = 'BANF-BU26-TEST-' + Math.random().toString(36).substr(2, 6).toUpperCase();        rec.driveRegCode = code;        rec.driveSignupComplete = true;        if (rec.stages.drive_signup) { rec.stages.drive_signup.status = 'completed'; rec.stages.drive_signup.detail = 'Registered: ' + code; rec.stages.drive_signup.timestamp = new Date().toISOString(); }        rec.stages.event_mgmt.status = 'completed'; rec.stages.event_mgmt.detail = 'Test complete'; rec.stages.event_mgmt.timestamp = new Date().toISOString();        rec.resumePoint = null; rec.lastInteraction = new Date().toISOString();        audit('Test: Drive signup', rec.displayName + ' registered: ' + code, 'test_harness', rec.email);        saveState(); toast(rec.displayName + ' test scenario completed!', 'success'); render('test_harness');      }    });  });  document.querySelectorAll('.th-reset').forEach(function(btn) {    btn.addEventListener('click', function() {      resetTestPersona(btn.dataset.email);      render('test_harness');    });  });  document.querySelectorAll('.th-view').forEach(function(btn) {    btn.addEventListener('click', function() {      showTestPersonaDetail(btn.dataset.email);    });  });  var resetAllBtn = document.getElementById('thResetAll');  if (resetAllBtn) resetAllBtn.addEventListener('click', function() {    STATE.pipeline.filter(function(r) { return r.isTestPersona; }).forEach(function(r) {      resetTestPersona(r.email);    });    toast('All test personas reset', 'success');    render('test_harness');  });}function resetTestPersona(email) {  var rec = findRecord(email);  if (!rec) return;  rec.selectedCategory = null; rec.selectedTier = null;  rec.selectedPaymentMethod = null; rec._paymentMethodLabel = null; rec._paymentDate = null;  rec.paymentStatus = 'not_started'; rec.commVerified = false;  rec.driveSignupComplete = false; rec.driveRegCode = null;  rec.resumePoint = (rec.rsvp === 'yes') ? 'membership' : null;  STATE.stages.forEach(function(s) {    if (s.id === 'email_scan' || s.id === 'evite_analysis') return;    if (rec.stages[s.id]) {      if (s.id === 'wf_payment_scan' && rec.wfPayment) return; // keep WF scan      rec.stages[s.id].status = (s.id === 'membership_rec' || s.id === 'event_mgmt') ? 'pending' : 'not_started';      rec.stages[s.id].detail = ''; rec.stages[s.id].timestamp = null;    }  });  // Re-apply WF auto-payment if present  if (rec.wfPayment && rec.wfPayment.confidence === 'high') {    rec.selectedCategory = rec.